"""Independent teaching diagrams for DLL and elevation evidence."""
def build_privilege_final_diagrams(assets, diagram):
    specs = [
      ('36-loader-context.svg','DLL 해석과 관측', ['DLL 요청 문맥','앱 유형 · OS · API · 플래그'], ['해석 규칙','API set · SxS · Known DLL','기존 모듈 · 경로 설정'], ['실제 관측','프로세스 시작 시각 · PID','Load Image · 전체 경로'], ['요청과 결과를 대조','폴더 목록만으로 선택을 단정하지 않음']),
      ('36-load-evidence.svg','위치 통제와 높은 실행 문맥', ['같은 구성 · 같은 시각의 증거','모듈 이름과 경로를 연결'], ['위치 통제','주체 · 파일과 폴더 ACL','실제 요청 권한 · 다른 제약'], ['실행 연결','선택 경로 · 로드 조건','트리거 · 높은 토큰'], ['조건부 위험과 실행 성공을 구별','파일 존재 ≠ 로드 ≠ 특정 함수 실행']),
      ('36-parser-boundary.svg','데이터 파서의 신뢰 경계', ['입력 파일 · 메시지','누가 만들고 바꿀 수 있는가?'], ['낮은 문맥의 통제','출처 · ACL · 크기','허용된 데이터 모델'], ['높은 문맥의 파서','런타임 · 타입 복원 규칙','호출 코드 · 서비스 계정'], ['권한 경계를 넘는 해석을 검토','위험 파서 제거 · 최소 권한 · 오류 격리']),
      ('37-access-layers.svg','접근 허가를 판단하는 다른 층', ['구체적인 요청','주체 · 객체 · 시각 · 요청 권한'], ['현재 실행 토큰','SID · 그룹 속성 · 특권','무결성 · impersonation'], ['대상 객체 규칙','mandatory label 정책','DACL · 다른 보호 조건'], ['요청과 모든 적용 조건을 함께 해석','관리자 이름만으로 허가를 추정하지 않음']),
      ('37-result-validation.svg','요청과 결과의 증거 연결', ['승격 요청 기록','원 세션 · 호스트 · 시각 · 선택'], ['도구 관측','작업 결과 · 새 세션 ID','연결만으로 High 아님'], ['Windows 관측','프로세스 · 사용자 SID','토큰 · 무결성 · 접근 결과'], ['같은 요청의 결과인지 교차 대조','High ≠ SYSTEM · 명령 실행 ≠ 새 세션']),
    ]
    for name,title,top,left,right,bottom in specs:
        nodes=[(40,25,720,90,top,''),(15,215,370,145,left,''),(415,215,370,145,right,'decision'),(35,475,730,110,bottom,'decision')]
        edges=[('220,115 220,165 200,165 200,215',[],0,0),('580,115 580,165 600,165 600,215',[],0,0),('200,360 200,420 260,420 260,475',[],0,0),('600,360 600,420 540,420 540,475',[],0,0)]
        (assets/name).write_text(diagram(title,800,625,nodes,edges,'독립 개념도. 두 종류의 증거를 대조하여 아래 판단으로 연결하며 실제 제품 화면이나 실행 결과가 아닙니다.').replace('<text ', '<text fill="#deeee9" font-size="18" font-family="Arial,sans-serif" '),encoding='utf-8')
    nodes=[(170,25,470,80,['기준선과 수집 범위','정책 · 토큰 · ACL · 로그 설정'],''),(170,190,470,80,['관측 사실 대조','요청 · 프로세스 · 결과'],''),(170,355,470,80,['개선과 정상 기능 검토','최소 권한 · 안전한 로더와 파서'],''),(170,520,470,80,['같은 기준으로 재검증','미수행 시험은 미수행으로 기록'],'decision')]
    edges=[('405,105 405,190',[],0,0),('405,270 405,355',[],0,0),('405,435 405,520',[],0,0),('170,560 70,560 70,65 170,65',['조건 변경 후','기준선 갱신'],75,310)]
    (assets/'37-review-cycle.svg').write_text(diagram('개선과 재검증의 반복',800,640,nodes,edges,'아래 재검증에서 왼쪽 경로로 기준선에 되돌아가는 순환. 실제 공격 실행 절차가 아닙니다.').replace('<text ', '<text fill="#deeee9" font-size="18" font-family="Arial,sans-serif" '),encoding='utf-8')
